// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testFuzz_property(address owner, address operator) public {
        vm.assume(owner != operator);
        vm.assume(owner != address(0));
        vm.assume(operator != address(0));

        vm.startPrank(owner);
        c.setApprovalForAll(operator, true);
        c.setApprovalForAll(operator, false);
        vm.stopPrank();

        bool result = c.isApprovedForAll(owner, operator);
        assertTrue(result == false);
    }
}
